<?php
$admissions = (int) ($totals['admissions'] ?? 0);
$discharges = (int) ($totals['discharges'] ?? 0);
$activeCases = (int) ($totals['active_cases'] ?? 0);
$currentInHouse = (int) ($totals['current_in_house'] ?? 0);
$maxDepartment = max(array_merge([1], array_map(static fn (array $row): int => (int) $row['total'], $departmentRows ?? [])));
?>
