<script>(function(){function loadRange(from,to){load_form('<?= base_url('dashboard/ipd') ?>?from_date='+encodeURIComponent(from)+'&to_date='+encodeURIComponent(to),'IPD Dashboard');}$('#ipd_apply_range').off('click.ipdDash').on('click.ipdDash',function(){loadRange($('#ipd_from_date').val(),$('#ipd_to_date').val());});$('.ipd-range').off('click.ipdDash').on('click.ipdDash',function(){var end=new Date(),start=new Date();start.setDate(end.getDate()-Number($(this).data('days')||0));function ymd(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}loadRange(ymd(start),ymd(end));});})();</script>